func renderRoutingConfigurationList(v []RoutingConfigurationListItem) string {
	parts := make([]string, 0, len(v))
	for range v {
		parts = append(parts, "")
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// at extends a violation path without aliasing the parent's array.
func at(p awserr.Path, segments ...string) awserr.Path { return append(slices.Clip(p), segments...) }

// renderFloat renders a number as Java's Double.toString does for the
// values a range constraint echoes: 900.0, 0.5.
func renderFloat(x float64) string {
	s := strconv.FormatFloat(x, 'f', -1, 64)
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}
